#!/usr/bin/env python3
from __future__ import annotations
import base64, hashlib, subprocess, zlib
from pathlib import Path

BASE = "d52e02fde2f17bef1b7dff68da53ae65e33e6de7"
PATCH_SHA256 = "52f2608cf9cfb6e9836255862052788ded51846742e6597b9a1b86368623bf83"
PATCH_ZLIB_BASE64 = ""
EXPECTED = {
    ".release/policy/authority-surface-contract.json",
    "README.md",
    "scripts/lib/assemble-content.mjs",
    "scripts/lib/projection-context.mjs",
    "scripts/lib/publication-context.mjs",
    "scripts/lib/schemaorg-vocabulary.mjs",
    "scripts/test-canonical-authority.mjs",
    "scripts/test-final-entity-contract.mjs",
    "scripts/test-machine-resources.mjs",
    "scripts/test-schemaorg-vocabulary.mjs",
    "scripts/validate-architecture.mjs",
    "scripts/validate-release-contract.mjs",
    "scripts/validate-source.mjs",
    "src/components/DocumentHead.astro",
    "src/components/GuideNavigator.astro",
    "src/data/retrieval/query-matrix-policy.json",
    "src/data/semantic/authority-profile.json",
    "src/data/semantic/clinic-assertion-provenance.json",
    "src/data/semantic/knowledge-graph.jsonld",
    "src/lib/canonical-authority.mjs",
    "src/lib/canonical-graph-facts.mjs",
    "src/lib/semantic-projection.mjs",
}

def run(*args: str, input_bytes: bytes | None = None) -> str:
    result = subprocess.run(args, input=input_bytes, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    if result.returncode:
        raise SystemExit(result.stderr.decode("utf-8", "replace") or result.stdout.decode("utf-8", "replace"))
    return result.stdout.decode().strip()

parent = run("git", "rev-parse", "HEAD^")
if parent != BASE:
    raise SystemExit(f"Unexpected migration parent: {parent}")
patch = zlib.decompress(base64.b64decode(PATCH_ZLIB_BASE64))
if hashlib.sha256(patch).hexdigest() != PATCH_SHA256:
    raise SystemExit("Embedded patch digest mismatch")
run("git", "apply", "--check", "-", input_bytes=patch)
run("git", "apply", "-", input_bytes=patch)
changed = set(run("git", "diff", "--name-only").splitlines())
if changed != EXPECTED:
    missing = sorted(EXPECTED - changed)
    extra = sorted(changed - EXPECTED)
    raise SystemExit(f"Migration scope drift missing={missing} extra={extra}")
print(f"PR401_CONSOLIDATION_PATCH_PASS files={len(changed)} sha256={PATCH_SHA256}")
